const d = $json;

const norm = (s) => String(s ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim()
  .toLowerCase();

// --------------------------------------------------
// FIRST MESSAGE
// --------------------------------------------------

const firstMessage = norm(d.firstMessage)
  .replace(/[.!?]+$/g, '')
  .trim();

let firstMessageMarca = null;
let firstMessagePago = null;

// Peugeot - Plan de Ahorro
if (firstMessage === '¡hola! quiero mas informacion sobre un peugeot') {
  firstMessageMarca = 'PEUGEOT';
  firstMessagePago = 'pda';
}

// Peugeot - Convencional / 0km
else if (firstMessage === '¡hola! quiero mas informacion sobre un peugeot 0km') {
  firstMessageMarca = 'PEUGEOT';
  firstMessagePago = 'contado';
}

// Citroen - Plan de Ahorro
else if (firstMessage === '¡hola! quiero mas informacion sobre un citroen') {
  firstMessageMarca = 'CITROEN';
  firstMessagePago = 'pda';
}

// Citroen - Convencional / 0km
else if (firstMessage === '¡hola! quiero mas informacion sobre un citroen 0km') {
  firstMessageMarca = 'CITROEN';
  firstMessagePago = 'contado';
}

// --------------------------------------------------
// MARCA
// --------------------------------------------------

const m = norm(d.marca);

let marca = m.includes('citroen')
  ? 'CITROEN'
  : m.includes('peugeot')
    ? 'PEUGEOT'
    : null;

// Si firstMessage define la marca, tiene prioridad
if (firstMessageMarca) {
  marca = firstMessageMarca;
}

// --------------------------------------------------
// FORMA DE PAGO
// Default: contado
// --------------------------------------------------

const p = norm(d.pago);

let pago = 'contado';

if (p === 'pda' || p.includes('plan')) {
  pago = 'pda';
}
else if (p.includes('financ')) {
  pago = 'financiado';
}

// Si firstMessage define el pago, tiene prioridad
if (firstMessagePago) {
  pago = firstMessagePago;
}

// --------------------------------------------------
// ORIGEN DE CAMPAÑA
// --------------------------------------------------

const origenEntrada = String(d.origin ?? '').trim();

const ORIGEN_CAMPANA = {
  'G5PFFXB5DC4T19R0C': {
    marca: 'PEUGEOT',
    pago: 'pda'
  },

  'G5PFHK1EQI5LVA07O': {
    marca: 'PEUGEOT',
    pago: 'contado'
  },

  'G5QI5JKME40S26SE9': {
    marca: 'CITROEN',
    pago: 'pda'
  },

  'G5QI2Z0EJAWCASTTS': {
    marca: 'CITROEN',
    pago: 'contado'
  }
};

const origenDetectado = ORIGEN_CAMPANA[origenEntrada];

if (origenDetectado) {

  // Utilizar la marca de la campaña si no fue identificada
  if (!marca) {
    marca = origenDetectado.marca;
  }

  // Utilizar el pago de campaña si no existe uno declarado
  if (!p && !firstMessagePago) {
    pago = origenDetectado.pago;
  }
}

// --------------------------------------------------
// ENTREGA USADO
// --------------------------------------------------

const truthy = (v) =>
  ['si', 'sí', 'true', '1', 'yes'].includes(norm(v));

const entregaUsado = truthy(d.vendeUsado);

// --------------------------------------------------
// TABLA DE REGLAS PILOT
// --------------------------------------------------

const PILOT = {
  PEUGEOT: {
    pda: 'G5PFFXB5DC4T19R0C',
    financiado: 'G5PFFXB5DC4T19R0C',
    contado: 'G5PFHK1EQI5LVA07O'
  },

  CITROEN: {
    pda: 'G5QI5JKME40S26SE9',
    financiado: 'G5QI5JKME40S26SE9',
    contado: 'G5QI2Z0EJAWCASTTS'
  }
};

// --------------------------------------------------
// BUSINESS TYPE
// --------------------------------------------------

const BT = {
  PEUGEOT: {
    pda: 3,
    financiado: 3,
    contado: 1
  },

  CITROEN: {
    pda: 17,
    financiado: 17,
    contado: 16
  }
};

// --------------------------------------------------
// ORIGEN CRM
// --------------------------------------------------

const ORIGEN = {
  PEUGEOT: {
    pda: 'Plan de Ahorro Peugeot',
    financiado: 'Financiado',
    contado: 'Contado'
  },

  CITROEN: {
    pda: 'Plan de Ahorro Citroen',
    financiado: 'Financiado',
    contado: 'Contado'
  }
};

// --------------------------------------------------
// PAYMENT
// --------------------------------------------------

const PAYMENT = {
  PEUGEOT: {
    pda: 223,
    financiado: 222,
    contado: 220
  },

  CITROEN: {
    pda: 221,
    financiado: 222,
    contado: 220
  }
};

// --------------------------------------------------
// USADO / DEFAULT
// --------------------------------------------------

const PILOT_USADO = 'FN7TPO109AG25R779';
const PILOT_DEFAULT = 'G5PFHK1EQI5LVA07O';

const PAYMENT_USADO = 227;
const PAYMENT_DEFAULT = 220;

const PAYMENT_FALLBACK = 220;

// --------------------------------------------------
// APLICAR REGLAS
// --------------------------------------------------

let regla;
let origen;
let pilot;
let businessTypeId;
let paymentId;

// --------------------------------------------------
// USADO
// --------------------------------------------------

if (entregaUsado) {

  regla = marca
    ? `${marca === 'PEUGEOT' ? 'Peugeot' : 'Citroën'} — Usado`
    : 'Usado';

  origen = 'Usado';
  pilot = PILOT_USADO;
  businessTypeId = 2;
  paymentId = PAYMENT_USADO;

}

// --------------------------------------------------
// PEUGEOT / CITROEN
// --------------------------------------------------

else if (marca) {

  regla =
    `${marca === 'PEUGEOT' ? 'Peugeot' : 'Citroën'} — ${ORIGEN[marca][pago]}`;

  origen = ORIGEN[marca][pago];

  pilot = PILOT[marca][pago];

  businessTypeId = BT[marca][pago];

  paymentId = PAYMENT[marca][pago];

}

// --------------------------------------------------
// DEFAULT
// --------------------------------------------------

else {

  regla = 'Default';

  origen = 'Default';

  pilot = PILOT_DEFAULT;

  // Default actual
  businessTypeId = BT.PEUGEOT.contado;

  paymentId = PAYMENT_DEFAULT;
}

// --------------------------------------------------
// PAYMENT FINAL
// --------------------------------------------------

const paymentIdFinal =
  Number(paymentId) || PAYMENT_FALLBACK;

// --------------------------------------------------
// OUTPUT
// --------------------------------------------------

return {
  json: {
    ...d,

    businesstypeid: String(businessTypeId),

    payment_id: paymentIdFinal,

    origenCRM: origen,

    pilot,

    regla,

    marcaNorm: marca,

    pagoNorm: pago,

    entregaUsado,

    firstMessageNorm: firstMessage
  }
};

